/**
 * Deterministic evidence review for Brain. This does not create memories or grant
 * tool permissions: only explicit, trusted observations supplied by the caller
 * are considered. The language model cannot promote a proposed memory itself.
 */
export type EvidenceOrigin = "user-confirmed" | "tool" | "inference";
export interface BrainEvidence {
  id: string;
  subject: string;
  proposition: string;
  polarity: "supports" | "refutes";
  origin: EvidenceOrigin;
  observedAt: number;
  /** 0..1, supplied by a trusted caller rather than generated by an LLM. */
  reliability: number;
}
export interface ReasoningAssessment {
  subject: string;
  proposition: string;
  verdict: "supported" | "refuted" | "conflicted" | "insufficient";
  confidence: number;
  supportingIds: string[];
  refutingIds: string[];
  warnings: string[];
}
const MAX_ITEMS = 200;
const TRUST: Record<EvidenceOrigin, number> = {
  "user-confirmed": 1,
  tool: 0.85,
  inference: 0.35,
};
const clean = (text: string) => text.normalize("NFKC").trim().toLocaleLowerCase("ru").replace(/\s+/g, " ");
const clamp = (v: number) => Math.max(0, Math.min(1, v));

/** An auditable, order-independent assessment; no fabricated sources or automatic memory writes. */
export function assessEvidence(
  subject: string,
  proposition: string,
  evidence: readonly BrainEvidence[],
  now: number = Date.now(),
): ReasoningAssessment {
  if (!Number.isFinite(now)) throw new TypeError("Invalid assessment time");
  const topic = clean(subject);
  const claim = clean(proposition);
  if (!topic || !claim || topic.length > 200 || claim.length > 1000) throw new TypeError("Invalid claim");
  if (evidence.length > MAX_ITEMS) throw new RangeError("Too many evidence items");
  const yes: { id: string; weight: number }[] = [];
  const no: { id: string; weight: number }[] = [];
  const seen = new Set<string>();
  for (const item of evidence) {
    if (!item || typeof item.id !== "string" || !item.id.trim() || item.id.length > 128 ||
      typeof item.subject !== "string" || typeof item.proposition !== "string" ||
      !Number.isFinite(item.observedAt) || !Number.isFinite(item.reliability) ||
      item.reliability < 0 || item.reliability > 1 ||
      !(item.origin in TRUST) || !["supports", "refutes"].includes(item.polarity)) {
      throw new TypeError("Invalid evidence");
    }
    if (seen.has(item.id)) continue; // repeated tool records must not boost confidence
    seen.add(item.id);
    if (clean(item.subject) !== topic || clean(item.proposition) !== claim || item.observedAt > now) continue;
    const ageDays = Math.max(0, (now - item.observedAt) / 86_400_000);
    const weight = TRUST[item.origin] * item.reliability / (1 + ageDays / 180);
    (item.polarity === "supports" ? yes : no).push({ id: item.id, weight });
  }
  const order = (a: { id: string }, b: { id: string }) => a.id.localeCompare(b.id);
  yes.sort(order); no.sort(order);
  // Aggregation saturates rather than scaling linearly with repeated observations.
  const combined = (items: { weight: number }[]) =>
    1 - items.reduce((product, item) => product * (1 - clamp(item.weight)), 1);
  const positive = combined(yes), negative = combined(no);
  const threshold = 0.25;
  const verdict: ReasoningAssessment["verdict"] =
    positive >= threshold && negative >= threshold ? "conflicted" :
    positive >= threshold ? "supported" : negative >= threshold ? "refuted" : "insufficient";
  const warnings: string[] = [];
  if (verdict === "conflicted") warnings.push("Противоречивые свидетельства: требуется проверка человеком.");
  if (verdict === "insufficient") warnings.push("Недостаточно надёжных свидетельств для вывода.");
  if (yes.some(e => e.weight < 0.2) || no.some(e => e.weight < 0.2)) warnings.push("Часть свидетельств имеет низкий вес.");
  return {
    subject: subject.trim(), proposition: proposition.trim(), verdict,
    confidence: Number((verdict === "conflicted" ? Math.min(positive, negative) : Math.max(positive, negative)).toFixed(3)),
    supportingIds: yes.map(e => e.id), refutingIds: no.map(e => e.id), warnings,
  };
}
